  spec jsonb := $spec$[
{"q": 22847, "quiz": 2126, "obj": "P1.COMPETITOR", "kind": "mcq", "was": "sentence", "body": "Why did the godavan come to the mung bean field?", "why": "في النص سببان يتنافسان، والمطلوب سبب المجيء لا سبب الرحيل: «We stopped putting pesticides in the field and so the godavan has come here to find a mate.» أما «new feeding grounds» فسبب طيرانها بعيداً في آخر القصة.", "opts": [{"t": "To hide from a pack of dogs.", "dx": "MIX", "key": false}, {"t": "To find a mate.", "dx": null, "key": true}, {"t": "To find new feeding grounds.", "dx": "MIX", "key": false}, {"t": "To eat the mung beans.", "dx": "JUMP", "key": false}]},
{"q": 22848, "quiz": 2126, "obj": "P2.ACROSS_PARA", "kind": "mcq", "was": "sentence", "body": "Why are the electric wires a danger for the godavans?", "why": "الدليل في فقرتين: قول سليم «But they fly so low that they might collide with the wires.» ثم في الفقرة الأخيرة «They have weak frontal vision, which means they can't always spot power lines in time to fly over them.»", "opts": [{"t": "They fly low, and their eyes are weak.", "dx": null, "key": true}, {"t": "They fly high, and the windmills are very tall.", "dx": "REV", "key": false}, {"t": "They are heavy, and they like to sit on the wires.", "dx": "JUMP", "key": false}, {"t": "They fly at night, and the wires are dark.", "dx": "GAP", "key": false}]},
